/**
 * Chain and token lookups for decoded swaps.
 *
 * The numbers inside an encoded swap are a SLIP-44 coin type (`0x02ca` = BNB) and a Meson token index scoped to that chain (`34` on BNB = BSC-USD).
 * The documented relayer endpoint `/api/v1/list` publishes symbols and decimals but *not* those two numbers, so it cannot be used to decode a swap.
 * The only published source that carries both is the explorer's own preset table, which `scripts/refresh-presets.mjs` lifts into src/presets.json.
 */
// ----- Contents (generated by `npm run index` — do not edit) -----
// L25  Chain & token names
// L30    generatedAt
// L33    chainCount
// L40    getChain()
// L46    chainName()
// L51    chainId()
// L56    tokenSymbol()
// L60  Explorer URLs
// L65    TX_PATH
// L74    TX_SUFFIX
// L79    txUrl()
// L88    addressUrl()
// ----- end of contents -----

import presets from './presets.json' with { type: 'json' }

// =============================================================================
//   Chain & token names
// =============================================================================

/** When presets.json was generated — logged at startup. */
export const generatedAt = presets.generatedAt

/** Number of known chains — logged at startup. */
export const chainCount = Object.keys(presets.chains).length

/**
 * The presets.json entry for a chain, or null if unknown.
 * @param {string} shortSlip44 e.g. "0x02ca"
 * @returns {{id:string,name:string,alias:string|null,explorer:string|null,addressFormat:string|null,tokens:Record<string,string>}|null}
 */
function getChain (shortSlip44) {
  if (!shortSlip44) return null
  return presets.chains[String(shortSlip44).toLowerCase()] ?? null
}

/** Human chain name, falling back to the raw id so output is never blank. */
export function chainName (shortSlip44) {
  return getChain(shortSlip44)?.name ?? `Unknown chain (${shortSlip44})`
}

/** Meson's network ID for a chain (e.g. "arb") — the key rpcs.meson.fi uses — or null if unknown. */
export function chainId (shortSlip44) {
  return getChain(shortSlip44)?.id ?? null
}

/** Token symbol for a chain-scoped Meson token index. */
export function tokenSymbol (shortSlip44, tokenIndex) {
  return getChain(shortSlip44)?.tokens?.[String(tokenIndex)] ?? `token#${tokenIndex}`
}

// =============================================================================
//   Explorer URLs
// =============================================================================

/** Path segment each explorer uses for a transaction. Default is `/tx/`. */
const TX_PATH = {
  tron: '/transaction/',
  ckb: '/transaction/',
  ton: '/transaction/',
  aptos: '/txn/',
  sui: '/txblock/',
}

/** Explorers that need a query string to pin the network. */
const TX_SUFFIX = {
  aptos: '?network=mainnet',
}

/** A block-explorer URL for a transaction on the given chain, or null. */
export function txUrl (shortSlip44, hash) {
  const chain = getChain(shortSlip44)
  if (!chain?.explorer || !hash) return null
  const fmt = chain.addressFormat ?? 'ethers'
  const path = TX_PATH[fmt] ?? '/tx/'
  return `${chain.explorer}${path}${hash}${TX_SUFFIX[fmt] ?? ''}`
}

/** A block-explorer URL for an address on the given chain, or null. */
export function addressUrl (shortSlip44, address) {
  const chain = getChain(shortSlip44)
  if (!chain?.explorer || !address) return null
  const fmt = chain.addressFormat ?? 'ethers'
  const path = fmt === 'aptos' ? '/account/' : '/address/'
  return `${chain.explorer}${path}${address}${TX_SUFFIX[fmt] ?? ''}`
}
